joi_block.script:
hold_ticks := 0
if (all(#Light).motionSensor_motion ==| false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 180) {
any(#Light).light_moveToBrightness(50.0, 0.0)
        delay(2 MIN)
any(#Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

